"""Native execution, task scheduling, and parallel algorithm contracts."""


def section(title, *paragraphs, rows=None, columns=None, bullets=None):
    result = {"title": title, "paragraphs": list(paragraphs)}
    if rows is not None:
        result["table"] = {"columns": columns or ["Member", "Description"], "rows": rows}
    if bullets:
        result["bullets"] = bullets
    return result


def entry(name, header, summary, *sections, covers=()):
    result = {"name": name, "header": header, "summary": summary, "sections": list(sections)}
    if covers:
        result["covers"] = list(covers)
    return result


THREAD_LIFETIME = section(
    "Lifetime and synchronization",
    "A launched child retains addresses inside its controlling object. Keep that object at a stable address until it has been joined. A completed but unjoined child is still a live backend handle for the move restrictions. Manipulating one controller concurrently from multiple owner threads is unsupported.",
    "Joining waits for backend termination before stack and TLS release. `alive()` observes the function-kernel flag, which can clear before the backend has finished its exit path; it is not a replacement for join. `wait_for()` polls that flag without releasing resources. `active()` probes the native tid with signal 0 and returns a snapshot.",
    "`sleep()` requests cooperative parking at the next native checkpoint; `awaken()` clears the park word and wakes it. `cancel()` requests cooperative exit and joins, so a function that never reaches a checkpoint can prevent it from returning. `terminate()` waits up to the configured internal millisecond budget, then sends SIGKILL on timeout. Linux SIGKILL can terminate the entire thread group; this is not a safe isolated stop for arbitrary user code. Neither path unwinds the interrupted callback's stack as a C++ cancellation exception.",
)


TASK_WAIT_LIFETIME = section(
    "Lifetime and resumption",
    "Suspended operations retain pointers to waiter nodes inside coroutine frames. The primitive, frame, and any referenced data must remain live at stable addresses until the operation completes. These primitives have no general cancellation registration or destructor that removes a queued waiter. Destroying a waiting task can therefore leave a dangling registration.",
    "Wakeup submits a frame to the global engine when one exists, otherwise resumes it inline on the notifying thread. Callers must allow continuation execution and reentry around notification. Internal list locks spin briefly; suspending the coroutine does not eliminate all spinning from the implementation. No FIFO or starvation bound follows from an awaitable interface.",
)


GUIDES = {
    "threads": {
        "summary": "Native-thread objects own or borrow worker stacks, retain backend join state, and publish results through a small controller payload. Arenas add fixed-capacity thread ownership or persistent queued workers; CPU and scheduler wrappers configure Linux execution separately.",
        "sections": [
            section("Thread types", columns=["Type", "Stack ownership and work", "Use"], rows=[
                ["`thread<Stack_Size>`", "Maps its own stack; one function per launch; can be relaunched after join.", "A separately controlled native thread with an initially empty state."],
                ["`auto_thread<Stack_Size>`", "Maps its own stack; starts in its constructor and joins in its destructor; immovable.", "A lexical owner for one callback lifetime."],
                ["`group_thread<Stack_Size>`", "Adopts and later unmaps a supplied stack; one function; startup handshake.", "Thread ownership inside a standard arena."],
                ["`void_thread<Stack_Size>`", "Borrows a supplied stack and runs a persistent queued worker.", "Worker implementations whose arena separately owns stack memory."],
                ["`async_thread<Stack_Size>`", "The same persistent worker scheme with a borrowed stack.", "The alternate worker controller interface; it is not a result-producing future."],
                ["`status_thread<Stack_Size, TLS_Limit>`", "Freestanding callback/controller with inline launch payload and bounded mapped reservations.", "Explicit negative-error start/join handling without allocating a launch argument box."],
                ["`standard_arena`", "Fixed stack of at most `maximum_threads` group controllers; per-child mapped stacks.", "`go` and realtime arena launches with arena-owned controller lifetimes."],
                ["`concurrent_arena`", "32 inline worker slots; separately mapped stacks; round-robin queued work.", "Persistent native workers used by `async`."],
            ]),
            section("Backends, stacks, and arguments",
                "Native wrappers use clone/clone3 with a fresh TLS frame under `__micron_freestanding`; hosted wrappers use pthread creation/join with an explicitly mapped stack. The wasm branches redirect `thread`, `auto_thread`, `threads`, and solo entry headers to the wasm thread API, while native arenas and their worker variants reject wasm. The coroutine task engine is also unavailable there.",
                "The default sizes are 524288 bytes for `thread` and `group_thread`, 262144 bytes for `auto_thread` and `status_thread`, and 131072 bytes for the concurrent-arena worker. `Stack_Size` is the complete mapping size; the backend attempts to protect and remove its lowest page from usable stack space. Ordinary guard setup is best effort; failure leaves the complete region usable. `status_thread` instead reports a guard-protection error.",
                "Ordinary launch arguments are decay-stored by value. The kernel invokes its stored function with argument lvalues, so a callable taking only an rvalue reference is not accepted by the launch constraint. Explicit pointer/reference-wrapper arguments retain caller-managed lifetimes. Hosted launch allocates an argument box; the freestanding backend allocates a payload and separate decayed argument objects. Setup failures report a thread error; only `auto_thread` supplies its own stack rollback guard around launch."),
            section("Results and cleanup",
                "A void callback publishes a none tag. A trivially representable result no larger than one pointer is packed into the pointer-sized result slot; larger results and selected nontrivial class results are separately allocated with a type-specific deleter. `result<R>()` accepts only trivially copyable `R` no larger than a pointer and returns a value-initialized `R` for a nonliteral result. It does not check that `R` matches the callback's result type.",
                "Retrieve a literal result before join: join clears the tag and destroys heap results. Ordinary wrappers expose no general typed extraction of the heap-result path. Child completion runs registered thread-local destructors and allocation/TLS exit hooks while TLS is still live. Attached TLS frames return through the host's release callback rather than being directly unmapped by the guest.",
                "Native sleep/cancel checkpoints are reached by the sleep wrappers and explicit checkpoint calls. An ordinary compute loop is not preempted by setting the control word. Process-wide alarm/suspend/resume handlers are installed by the thread support; application handlers for those signals can interact with this behavior."),
            section("Joining and solo helpers",
                "`solo::spawn<Tr>` constructs a unique owning pointer to a thread object; default `Tr` is `auto_thread<>`. Pointer overloads of `join` and `dismiss` clear that owner after forwarding the call. `dismiss` still joins; it is not detach. `solo::kill` forwards cooperative `cancel`, while `terminate` and `force_stop` forward the hard-stop interface. `park` changes CPU affinity rather than the native park word; `yield(thread)` sends the alarm signal.",
                "Join return conventions differ: regular/group/worker controllers generally use 0 for successful or empty join; `auto_thread::join` uses 0 after release and 1 if already released, and its successful `try_join` returns 1. `solo::try_join(owner)` clears the owner only for return 1, so a successful regular-thread try-join leaves an empty controller allocated.",
                "`can_join()` calls the backend try-join, not a pure ownership query. Hosted `pthread_tryjoin_np` actually reaps a completed thread, but `can_join` does not clear the stored handle. Avoid using that query before a later join on hosted wrappers. `solo::is_joinable` converts `can_join()` to bool, including a positive busy error, so it does not reliably distinguish an exited thread from a busy one."),
            section("Arena startup and limits",
                "The standard global arena is initialized through constructor/boot hooks and intentionally retained for process lifetime. The concurrent global arena is initialized by `start_concurrent_pools()` unless startup concurrency is configured; it creates at most `min(cpu_count(), 32)` workers. `end_concurrent_pools()` does not shut them down or null the pointer. Concurrent calls to the plain initialization bookkeeping are not supported.",
                "`go(fn, args...)` creates an arena thread, selecting a core using the current arena affinity distribution. `go(core, fn, args...)` chooses an explicit core. `realtime` selects FIFO intent and best-effort native settings; permission or affinity failure is not consistently surfaced by those arena paths. The root `realtime(core, priority, fn, ...)` overload forwards an extra priority argument to a creation overload that does not accept it and is ill-formed when instantiated.",
                "`maximum_threads` is 1024 by default, 256 with `MICRON_LOW_THREAD_COUNT`, 4096 with `MICRON_HIGH_THREAD_COUNT`, or 32768 with `ABSURD_THREAD_COUNT`, in that precedence order. `concurrent_threads` is always 32. These are arena slot bounds, not guarantees that the operating system can create that many threads."),
            section("Cost model", "Thread launch includes mapping, TLS construction/initialization, argument storage, and an OS thread-creation operation. Join has no bounded elapsed time. Arena placement and list queries can scan the arena; burden selection scans existing threads and their CPU masks. Persistent workers amortize thread creation across queued callbacks but retain their stack/TLS mappings and fixed worker queues. These storage and syscall differences do not establish a measured speedup for any variant."),
        ],
        "types": [
            entry("micron::thread", "thread/thread_types/reg_thread.hpp", "A native-thread controller that maps and owns its callback stack and TLS release state.",
                section("Construction and operations", "Default construction is empty. A function constructor starts one child; `operator[](fn, args...)` joins the prior child and starts another. Destruction joins and releases. `join`, `dismiss`, and successful `try_join` release the stack, TLS, and retained result. Copying is deleted; move is permitted only from a controller with no backend handle, and move assignment first joins/releases its destination.", "`stack()` exposes the owned mapping without transferring it and `stack_size()` returns the template size. `native_handle()` and `thread_id()` return the kernel tid obtained from the selected backend, not a pthread handle. `stats()` returns zero while the callback is alive, otherwise its final resource-usage snapshot. The literal-result, sleep, signal, and stop protocols are described above."), THREAD_LIFETIME),
            entry("micron::auto_thread", "thread/thread_types/auto_thread.hpp", "An immovable thread owner that starts from a callback and joins automatically at scope exit.",
                section("Ownership and operations", "There is no default constructor. Construction maps the stack separately from the parent stack, marks the payload alive before launch, and rolls back that mapping if launch unwinds. Destruction joins a retained child. `operator[]` joins and relaunches using the same control object. `cleanup()` joins; it is not an asynchronous release.", "`join()` and `dismiss()` return 0 after release and 1 if empty; successful `try_join()` returns 1, also the already-released value. `result<R>()` waits without joining and must precede join. `stack()` returns a byte pointer; stack ownership remains here. Copy and move are deleted because the child and kernel retain controller addresses."), THREAD_LIFETIME),
            entry("micron::group_thread", "thread/thread_types/group_thread.hpp", "A one-callback controller that adopts ownership of a caller-supplied mapped stack.",
                section("Adoption and launch", "The prepared constructor takes `thread_attr_t`, adopts its stack pointer and scheduling fields, and launches. The attributes argument is not cleared by this const-reference adoption; it must be treated as a transferred stack description rather than an independent owner. Release unmaps exactly `Stack_Size` bytes, so the supplied mapping and template size must agree.", "After launch the constructor waits up to the internal start-handshake budget for the child to publish `started`. On timeout it requests cooperative exit, joins, releases, then reports an error; the join can still wait indefinitely if the child never reaches a checkpoint. Scheduling fields are retained as intent; the launch helper itself does not apply them.", "The controller can be default-constructed empty. Copying is deleted and move rejects any retained backend handle. `attrs()` exposes its attributes as a const reference. Result, observation, signal, and cooperative-control behavior follows the regular thread controller."), THREAD_LIFETIME),
            entry("micron::void_thread", "thread/thread_types/void_thread.hpp", "A persistent callback worker borrowing a caller-provided stack mapping.",
                section("Work and ownership", "Prepared construction starts a worker, optionally submitting an initial callback. `operator[](fn, args...)` decay-captures a callback and values into its `lambda_queue<256>`, then release-publishes a work token. The worker drains callbacks serially and futex-waits when empty. The ring/payload bounds and callable-size constraints of `lambda_queue` still apply.", "The arena owns the stack; this controller releases only its TLS and handle state. `stop()` requests exit and wakes the work word. Stop is tested before and between callbacks, and can abandon queued callbacks. A running callback is allowed to finish; stop does not interrupt it. Join/destruction stop and join the worker. There is no result, cancel, sleep, signal, or alive interface; those operations are deleted.", "`get_status()` returns the work token and `is_working()` samples it; the token is a wake/work signal, not an exact completion counter for a submitted callback. `stats()` retries an ordinary resource-usage copy against a sequence counter; concurrent non-atomic payload accesses have the C++ data-race limitation of that copy scheme. Move is restricted to a controller without a retained backend handle.")),
            entry("micron::async_thread", "thread/thread_types/async_thread.hpp", "An alternate persistent worker controller using the same borrowed-stack queue kernel as `void_thread`.",
                section("Operations", "Prepared construction starts the same `__worker_kernel`, and `operator[]` enqueues a decay-captured callback in `lambda_queue<256>`. Stop release-stores the exit request and wakes the work token. The implementation does not expose a template parameter for a custom worker kernel despite the introductory source comment.", "Stack ownership, TLS release, joining, non-result status observations, deleted control operations, sequence-copy usage statistics, and move restrictions are the same as `void_thread`. There is no asynchronous value result or future returned by this type.")),
            entry("micron::status_thread", "thread/status_thread.hpp", "An immovable bounded freestanding callback thread with inline launch state and explicit negative-error setup.",
                section("Bounds and lifecycle", "`Stack_Size` defaults to 262144 bytes and must be at least four default pages and a page multiple. `TLS_Limit` defaults to 1048576 bytes and must lie between one page and 16 MiB. `reservation_bytes` is their sum; `mapped_bytes()` reports the actual mapped stack plus TLS size when active.", "`start(void(*)(void*), context)` returns 0 on success, `-busy` for an occupied controller, `-invalid_arg` for a null callback or unsuitable page geometry, and negative setup errors otherwise. Hosted use returns `-op_not_supported`. Attached freestanding execution is rejected. TLS-template size and alignment limits are checked before/after mapping; partial failure releases resources and leaves an empty reusable owner.", "The callback and context are borrowed until join; no argument box or typed result is allocated. `try_join()` returns `-busy` while running or 0 after release; `join()` and destruction wait then release. Callback cancellation is the callback's own protocol. The public type provides no generic thread cancel/terminate methods.")),
            entry("micron::thread_attr_t", "thread/thread_types/thread_impl.hpp", "A non-owning/native-control descriptor carrying thread identifiers, TLS, scheduling intent, and a stack address.",
                section("Fields and transfer", "`parent` is the thread-group id; `pid` is the freestanding kernel tid; `ctid` is the address-bound CHILD_CLEARTID join word; `tls` is the child TLS frame; `pth` is the hosted pthread handle. Scheduling fields are `sched_policy`, `sched_priority`, `sched_niceness`, and `detach_state`; stack fields are `stack_size` in bytes and `stack_addr`.", "The descriptor's destructor does not join, unmap, or free TLS. Move transfers the fields and clears source handle/stack state; it cannot safely relocate an active `ctid`. `clear()` clears handle/TLS/stack state without releasing resources. The constructor accepting `pthread_attr_t` ignores that argument. Passing this descriptor to a wrapper determines whether its stack is adopted or borrowed.", "`thread_returns` names callback-kernel return_success, return_force, and return_fail; `join_status` names join_success, join_fail, join_allowed, and join_busy. Wrapper methods do not consistently return these enums, so inspect their documented integer conventions."), covers=("micron::thread_returns", "micron::join_status")),
            entry("micron::thread_t", "thread/arena.hpp", "An arena record combining a `cpu_t<true>` mask descriptor and one concrete thread controller.",
                section("Access and lifetime", "Both `cpu_mask` and `thread` are public. `operator()()` returns the controller, `stats()` forwards its usage snapshot, and `attrs()` requires the concrete controller's matching member. Arena references and pointers to this record remain valid only until its slot is destroyed/reused or its arena is destroyed.", "`name()` asks `micthread::get_name`, whose implementation ignores the requested tid and uses PR_GET_NAME for the calling thread. It therefore does not reliably return the represented worker's name. The 32-byte result is owned by value. This wrapper adds no synchronization to direct access of its public fields.")),
            entry("micron::standard_arena", "thread/pool.hpp", "The public alias for the fixed-capacity standard arena of `group_thread<>` records.",
                section("Storage and operations", "Aliases `arena::__default_arena<thread_stack_size, group_thread<>>`. The underlying template exposes `type = thread_t<Tr>` and `thread_class = Tr`, stores at most `maximum_threads` records inline in an `fsstack`, and maps one stack for each created child. Creation/list/cleanup operations serialize through an arena mutex.", "`create`, `create_at`, `create_burden`, and their realtime variants append a record and return a reference. Burden selection counts existing affinity masks rather than sampling CPU utilization. Realtime/affinity/name changes are best effort. `clean()` waits for the most recently added child before popping it, so later long-lived work delays reclamation of earlier completed slots. `join_all(retries)` consumes one shared retry budget and eventually performs a blocking join; its retry count is not an elapsed-time bound.", "`list()` allocates an immutable vector of borrowed record pointers. Pop/cleanup invalidates pointers to removed records. Several optional administrative members are incomplete for the provided record: priority methods refer to nonexistent `rf.priority`, `move_thread` uses nonexistent record accessors, and `contains(record)` calls `record.native_handle()` rather than its nested controller. Those instantiations are ill-formed. `count()` reads the stack size without taking the arena mutex.", "Copy and move are deleted. Destruction joins all children. The global standard pool is deliberately not destroyed; users must finish work whose captured state has shorter lifetime."), covers=("micron::arena::__default_arena", "micron::arena::__default_arena::type", "micron::arena::__default_arena::thread_class")),
            entry("micron::concurrent_arena", "thread/pool.hpp", "The public alias for a fixed array of persistent queued native workers.",
                section("Storage and submission", "Aliases `arena::__concurrent_arena<>`, whose `Tr` must be exactly `void_thread<Sz>`. It owns 32 inline `thread_t<Tr>` slots and remembers the separate mappings because worker release clears its borrowed stack pointer. `create()` launches one worker up to the 32-slot bound. `add(fn, args...)` holds the arena mutex, selects the next active worker round-robin, enqueues its callback, and returns that worker record.", "`type` is `thread_t<Tr>` and `thread_class` is `Tr`. `count()` returns the fixed array size, 32, not the number of launched workers. `list()` and several searches also traverse all 32 slots, including unused slots. Submission requires at least one created worker. `stop_all` requests exit; `join_all` joins them, and destruction stops, joins, then unmaps all remembered stacks.", "The administrative priority and record-based contains helpers have the same nonexistent-member instantiation problems as the standard arena. Worker sleep/cancel/await forwarding targets operations deleted by `void_thread` and cannot be used with this arena. Neither the array nor records may be relocated while workers are active; copy and move are deleted."), covers=("micron::arena::__concurrent_arena", "micron::arena::__concurrent_arena::type", "micron::arena::__concurrent_arena::thread_class")),
            entry("micron::schedulers", "thread/scheduling.hpp", "Names Linux FIFO, round-robin, deadline, normal, idle, and batch scheduling policies.",
                section("Values", "`fifo`, `roundrobin`, `deadline`, `normal`, `idle`, and `batch` map to the corresponding Linux values. `none` is the explicit `0xFFFFFFFF` sentinel. The free `get_scheduler()` queries the calling process/thread id and reports a system error if the query fails.")),
            entry("micron::scheduler_t", "thread/scheduling.hpp", "A cached Linux scheduling-policy and scheduling-attributes descriptor.",
                section("Configuration", "Construction queries `sched_attr` for a pid. Copy copies the cache; move transfers it and resets the source to `schedulers::none`. `set_scheduler(policy)` updates the cache only, resetting relevant nice/priority/deadline fields. `load_scheduler(pid)` applies the policy first and the full cached attributes second; either failure reports a system error, and a partial change is not rolled back.", "`load_scheduler` applies a legacy priority-99 scheduler call for deadline policy before its attribute call; that can fail before deadline attributes are applied. `enable_deadline(time)` sets runtime to `time/2`, deadline to `(time/4)*3`, and period to `time` only for deadline policy and `time >= 1024`. These are kernel scheduling time units, not the floating millisecond sleep interface. `get_priority()` returns cached nice for ordinary policies or realtime priority for FIFO/RR. Classification helpers do not query the kernel again.", "State and copies are inline with constant wrapper work; construction/application perform syscalls. This descriptor does not own a thread, restore previous scheduling at destruction, or serialize concurrent reconfiguration.")),
            entry("micron::cpu_t", "thread/cpu.hpp", "A CPU-affinity mask and cached scheduler descriptor bound to the pid selected at construction.",
                section("Mask and updates", "`D` defaults to false: the initial mask is empty, or all reported cores up to 1024 for `D = true`. The object stores a fixed 1024-bit Linux mask and caches `cpu_count()`. Index checks compare against that reported count. On systems reporting more than 1024 cores, `set_core`, `at`, `clear_core`, and `set_all` do not separately clamp the mask index; use only representable indices.", "`clear`, `set_core`, and `clear_core` change the local mask. `update_cores` applies it; `update` first enables all cores, applies cached scheduling, then applies the mask. Affinity setters generally do not report kernel failure. `pin(c)` clears the mask to one core and applies it, using the caller's current CPU when the sentinel is supplied. Copying retains the stored pid, rather than rebinding to the copying thread.", "Frequency, governor, online, priority, and cache-line helpers forward to Linux/sysfs interfaces and can fail due to permissions or missing files. `core_count()` is reported system count, not the count of permitted CPUs; `active_count()` counts set mask bits. Mask operations take constant bounded space, with set-all linear in the reported count.")),
            entry("micron::proc_t", "thread/cpu.hpp", "An immovable lazily allocated runtime CPU-information snapshot, separate from compile-time ISA dispatch.",
                section("Probe and storage", "Construction caches `cpu_count()` and zeroes feature flags. `instance()` returns a function-local singleton. `probe()` serializes the initial CPUID/ID-register feature probe with a three-state atomic byte; `probe_full()` additionally populates up to 256 core/cache records. Large raw/core data is mmap-allocated on first probe and unmapped at destruction; failure leaves empty/default results and is not retried after the probe is marked complete.", "`features`, `vendor`, and `arch_level` trigger the basic probe; `core(n)` triggers the full probe and returns a static empty record for `n >= 256` or missing data. Raw family/model/stepping or ARM implementer/part accessors do not trigger a probe. `l1d`, `l1i`, `l2`, and `l3` require a completed full probe and do not check their `core_id` against 256. `raw() const` does not probe; mutable `raw()` probes and exposes internal storage without locking it.", "`has_*` convenience queries inspect feature bytes. These report observed hardware information; they do not change which instructions compiled library paths may execute, or automatically arrange OS vector-state support. `simd_width()` reports the compile-time SIMD width (zero for scalable vector tiers), while SVE vector-byte queries execute the compiled SVE width instruction only on the selected capability path.", "Probe copies bounded architecture data and core records; subsequent feature queries are constant work. Returned references and pointers borrow the snapshot and must not outlive it. Concurrent direct mutation through `raw()` or `__ensure_data()` is unsupported."),
                section("Supporting records", columns=["Type", "Fields and meaning"], rows=[
                    ["`cpu_freq_t`", "Current/minimum/maximum frequency in Hz and a 32-character governor string, populated from sysfs."],
                    ["`cpu_vendor`", "Enumerates unknown, Intel/AMD/x86 vendors, and the listed ARM implementers; a probe maps architecture vendor ids to these values."],
                    ["`cache_info_t`", "Cache type/level, line size, associativity, set count, and byte size."],
                    ["`core_info_t`", "Core type, cluster, frequency, and five cache records; ARM fills four and clears the fifth."],
                    ["`cpu_features_t`", "Byte-valued common, x86, and ARM feature fields. Unsupported architecture fields stay zero, and some common flags map to a related architecture capability rather than an independent test."],
                ]), covers=("micron::cpu_freq_t", "micron::cpu_vendor", "micron::cache_info_t", "micron::core_info_t", "micron::cpu_features_t")),
            entry("micron::micthread::tier", "linux/sys/micthread/threads.hpp", "Describes whether native TLS-template and clone support can launch freestanding threads.",
                section("Capabilities and low-level protocol", "`none` means no usable TLS template, `legacy` means a template with the legacy clone path, and `full` means a template with clone3 currently selected. `available()` is true for either usable tier. `threads_available()` is always true for the hosted wrapper branch and asks this capability query for the freestanding branch.", "`micthread::spawn` requires a supplied usable stack, TLS pointer, and stable join word. It allocates the decayed launch payload, calls clone3/legacy clone, and returns a kernel tid or `thread_failed` with errno recorded. `join(ctid)` acquire-checks the kernel-cleared word and uses a shared-class futex wait; private futex waits would miss the kernel's CHILD_CLEARTID wake. `try_join` returns 0 for cleared or positive `error::busy` otherwise.", "`stack_region` contains `low` (lowest usable byte) and `usable` (byte count). `guard_stack` attempts to protect the lowest default page, then returns the remaining region, falling back to the whole region if protection fails. `tid_t` is `pid_t`. The compatibility enums `thread_create_state`, `thread_mutex_type`, `cancel_state`, `cancel_type`, and `thread_sched_inherit` name legacy joinability/mutex/cancellation/scheduling values; they do not by themselves configure the current high-level wrappers."),
                covers=("micron::micthread::stack_region", "micron::micthread::tid_t", "micron::micthread::thread_create_state", "micron::micthread::thread_mutex_type", "micron::micthread::cancel_state", "micron::micthread::cancel_type", "micron::micthread::thread_sched_inherit")),
            entry("micron::posix::clone_args", "linux/sys/clone.hpp", "The Linux clone3 argument descriptor with 64-bit ABI fields on every supported native architecture.",
                section("Fields and launch", "Fields contain flags, pidfd output address, child/parent-tid output addresses, exit signal, lowest stack address and byte size, TLS argument, set-tid array address/count, and cgroup descriptor. Address fields use integer representations rather than owning pointers. `clone3_kernel` passes the complete descriptor directly to the kernel.", "`clone3_spawn` initializes the child-tid word before launch, chooses clone3 through a probe gate, and falls back to legacy clone only on ENOSYS. Architecture trampolines preserve the callable/payload through the child stack pivot; i386 builds a TLS user descriptor, and arm32/i386 use the reversed legacy argument convention. Neither low-level launch owns the supplied stack or TLS.", "`clone_flags` names Linux sharing, namespace, TLS, pid, and tracing bits; `posix_process_flags` names process-spawn attribute bits. The templated legacy `clone<Sz, Fn>` allocates a payload and argument copies, cleans the independent parent copy for a nonshared address space, and returns the raw signed syscall result. The callback-style clone overload borrows its payload. These are low-level process/thread primitives, not automatically joined owners."), covers=("micron::posix::clone_flags", "micron::posix::posix_process_flags")),
            entry("micron::coro::executor", "thread/coroutine/executor.hpp", "A structural concept requiring frame submission and an observable worker count.",
                section("Requirements", "For an executor `E`, `e.submit(coro::__frame_base*)` must return void and `e.worker_count()` must be convertible to `u32`. The concept does not check frame ownership, scheduling fairness, exception behavior, or shutdown protocol. A submitted frame must remain live until all possible resumptions are finished.")),
            entry("micron::coro::work_stealing_executor", "thread/coroutine/executor.hpp", "A non-owning concrete executor referring to a coroutine `engine`.",
                section("Operations", "`executor_tag` is void. Default construction has no engine; submitting then traps. `submit(frame)` forwards to the engine and `worker_count()` returns its `n`, or zero for null. `default_executor()` starts the global runtime and returns a view of its engine. Copying the executor copies its borrowed pointer; stopping/restarting the runtime invalidates previously obtained engine views."), covers=("micron::coro::work_stealing_executor::executor_tag",)),
            entry("micron::coro::any_executor", "thread/coroutine/executor.hpp", "A non-owning erased executor containing an object pointer and two function pointers.",
                section("Operations", "`make(e)` binds any object satisfying `executor`, retaining its address without allocating or extending its lifetime. `submit(frame)` invokes the erased submit function and traps if unbound. `worker_count()` returns zero when unbound. These methods are noexcept, so an exception escaping a custom executor cannot propagate through them. Copies retain the same borrowed executor; that executor and its scheduling state must outlive all uses.")),
        ],
        "sources": ["thread/arena.hpp", "thread/callbacks.hpp", "thread/coroutine/executor.hpp", "thread/cpu.hpp", "thread/pool.hpp", "thread/scheduling.hpp", "thread/spawn.hpp", "thread/status_thread.hpp", "thread/thread.hpp", "thread/threads.hpp", "thread/thread_types/async_thread.hpp", "thread/thread_types/auto_thread.hpp", "thread/thread_types/group_thread.hpp", "thread/thread_types/reg_thread.hpp", "thread/thread_types/sig_callbacks.hpp", "thread/thread_types/thread_impl.hpp", "thread/thread_types/void_thread.hpp", "linux/sys/clone.hpp", "linux/sys/micthread/threads.hpp", "linux/sys/micthread/tls.hpp", "bits/__thread_exit_hook.hpp", "memory/stack_constants.hpp"],
    },
    "parallel": {
        "summary": "Parallel range algorithms return lazy `task` objects and divide random-access ranges into coroutine work. A separate reusable scan workspace accepts a caller-supplied joined executor without a coroutine dependency.",
        "entry_overrides": {
            "micron::parallel::find": "Returns a lazy `task<It>` that finds the leftmost matching iterator, or the supplied end iterator. Execute or await the task to perform the search.",
            "micron::parallel::fill": "Returns a lazy `task<void>` that assigns the supplied value across a random-access range when executed.",
        },
        "sections": [
            section("Execution and constraints",
                "Most interfaces in `parallel/algo.hpp` return `micron::task<R>`. Calling one constructs a lazy task; discarding it performs no range work. Use `co_await`, `coro::sync_wait`, or a scheduling interface and retain the input/output storage until completion. The task engine must be available; the task-based engine rejects wasm. `scan_workspace.hpp` is independent of the coroutine engine.",
                "Range types must support subtraction, addition, and indexed access where used. Sorting additionally passes a contiguous `T*` into serial kernels, so a nominal random-access iterator is insufficient there. Ranges must be valid and ordered; a negative `last - first` is converted to a huge `usize`. Output spans and second inputs are not length-checked. Functions and predicates are copied into task/leaf state and can execute concurrently; captured shared mutable state requires its own synchronization.",
                "The grain is `max(1024, n / (workers * 8 + 1))`, using one worker if no global engine yet exists when the task is created. Recursive bisection forks the left child, calls the right child, then joins. A fixed grain therefore creates order `n/grain` leaves and linear total leaf work for ordinary elementwise operations. Scheduling, frame allocation, callbacks, and synchronization add costs; no linear speedup is guaranteed."),
            section("Elementwise and memory operations", columns=["Functions", "Effects and units"], rows=[
                ["`for_each`, unary/binary `transform`", "Visit dereferenced elements; transform writes the corresponding output index. Binary transform assumes the second range is long enough."],
                ["`fill`, `generate`, `reverse`, `reverse_copy`", "Assign a value, invoke a generator, swap symmetric elements in place, or write reversed elements to a separate range. Reverse uses copied temporaries."],
                ["`round`, `ceil`, `floor`, `add`, `multiply`, `divide`, `subtract`, `pow`", "Delegate each leaf to the matching serial range function; retain that function's type, numeric, and ISA constraints."],
                ["`sin`, `cos`, `tan`, `asin`, `acos`, `atan`, `sinh`, `cosh`, `tanh`, `exp`, `log`, `log10`, `sqrt`, `cbrt`", "Convert each element to double, call the scalar math function, and cast the result back. Domain and representability checks are not added."],
                ["`asinh`, `acosh`, `atanh`", "Use the explicit logarithm/square-root formulas in the leaf, with double intermediates and no domain protection."],
                ["`copy_n`, `move_n`", "Count elements and delegate chunks to the serial copy/move helpers. Source/destination lifetime rules remain those of those helpers."],
                ["`set_n`, `zero_n`, `swap_n`", "Count bytes, reinterpreting storage as unsigned-char ranges. Arbitrary byte patterns do not necessarily form valid nontrivial objects."],
            ]),
            section("Search and predicates",
                "`find`, `find_if`, `find_if_not`, `mismatch`, `adjacent_find`, `search`, and `search_n` select the leftmost matching index by combining subtree results. `find_last` and `find_last_if` retain the rightmost. The no-match result is the first range's end iterator; mismatch returns only that iterator, not a pair. An empty search pattern or zero run length returns the first iterator.",
                "Leaves can stop locally, but other subtrees are not cancelled once a result is found. All/any/none/contains similarly reduce local booleans without global early termination. Count/count-if visit every selected element. Ordinary find/mismatch/adjacent checks use at most linear element comparisons; naive subsequence and repeated-value search use worst-case `O(n*m)` comparisons for pattern/run length `m`."),
            section("Numeric reductions and ordering",
                "`reduce(first, last, init, op)` reduces each nonempty leaf from its first element, combines left and right results, then applies `op(init, combined)` once. It requires an associative operation for grouping-independent semantics; it preserves left-to-right operand order at combine sites but changes parenthesization. Floating-point results need not match a serial fold bit for bit.",
                "`sum` defaults to a wide accumulator: `f128` for floating elements, `intmax_t` for signed integral elements, and `umax_t` otherwise. Mean defaults to `f64`; geometric and harmonic means default to `flong` and use direct product or reciprocal-sum formulas. No overflow, zero-denominator, or logarithmic-stability checks are added. `inner_product` sums products in `T` and adds init once.",
                "Empty sum/mean/geometric/harmonic/min/max return a value-initialized result. Empty reduce and inner-product return init. `min_at` and `max_at` return end on empty input and the leftmost equal extremum otherwise. Value min/max require a default-constructible result for the empty path. `is_sorted` checks both leaf interiors and adjoining leaf boundaries. Total work is linear apart from element arithmetic and task overhead."),
            section("Compaction and scans",
                "`where` and its alias `filter` retain matching elements in original order; `unique` retains the first element of each adjacent equal run rather than removing all duplicate values globally. They return the number written. A single grain compacts serially. Larger ranges count matches per block, compute offsets serially, and traverse the input again to write output; predicates can be called twice per element and must give consistent results.",
                "For safe parallel compaction use disjoint input/output storage. In-place or partial overlap can let one block overwrite input another block has not read, particularly for `unique`'s predecessor comparison. Auxiliary count/offset storage is `O(number_of_blocks)` and total work is linear.",
                "`scan` produces an inclusive associative scan. It computes block totals, a serial carry sequence, and per-block output. `scanl` writes init at output zero, writes inclusive prefixes after it, then applies `op(init, prefix)` to each; it requires `n + 1` output elements even for empty input. Its shifted write means identical input/output storage is not a safe general alias. `scan` can use identical or disjoint ranges when element operations permit; partial overlap is unsupported. Both change grouping and can differ from a serial nonassociative or floating fold. Coroutine scan allocates two block-sized vectors on multiblock input."),
            section("Sorting",
                "`parallel::sort::merge` and `stable` fork recursive halves and then run the serial merge kernel. `quick` and `sort` use a median-of-three partition with a depth budget of twice floor-log2(n), falling back to serial merge sort at the grain or depth limit. Quick's partitioning does not preserve equal-element order. With suitable comparison and the serial-kernel contracts, total comparison work is `O(n log n)` in the worst case; serial partition/merge phases limit available parallelism. Temporary allocation follows the serial merge kernels.",
                "`radix` first scans key min/max serially, biases keys by the minimum, then performs stable byte-digit histogram, offset, and scatter passes. It allocates an `n`-element scratch vector and two `256 * blocks` counter vectors. For `d` processed bytes its work is `O(n + d * (n + 256*blocks))`; offsets are computed serially. Integral/custom keys are converted to `umax_t`; wider or non-order-preserving conversions are unsupported. Float overloads accept 32- or 64-bit representations and transform their sign bits into ordered unsigned keys; NaNs follow representation-derived ordering rather than ordinary numeric comparison. Equal transformed keys retain order.",
                "The `_range` wrappers forward `begin/end` and return the same lazy tasks; they add no bounds, synchronization, or storage ownership. `parallel/pipeline.hpp` declares no pipeline facility, and `poll.hpp` contains no polling implementation."),
            section("Native-loop alternatives",
                "`parallel_for<Fn>(container)` in `parallel/for.hpp` is a separate synchronous `micron` function. It splits into up to `cpu_count()` contiguous segments, launches independent `thread<>` owners, calls `Fn(iterator)` for each iterator, and joins all before returning. Its temporary owner stack has a fixed 1024-slot bound; more than 1024 selected segments is unsupported.",
                "`fork_for<Fn>` submits segments through the concurrent native arena and waits on selected workers' work tokens. It requires concurrent pools to be initialized. The token is a wake/work flag, not a per-job completion count; it must not be treated as a general precise batch fence. Both helpers assume pointer-like random-access container iterators despite their broader iterable constraint."),
        ],
        "types": [
            entry("micron::parallel::scan_workspace", "parallel/scan_workspace.hpp", "A reusable inclusive-scan workspace with setup-owned block metadata and caller-selected joined execution.",
                section("Storage and executor protocol", "Construction fixes a maximum block count and allocates vectors for totals, carries, and item records using `allocator_serial` with locking disabled. A zero-capacity workspace still allocates one slot in each vector but rejects scan. Copying is deleted; its const capacity and member ownership do not provide a reusable move-assignment interface.", "`scan(input, output, count, operation, executor)` requires an associative nonthrowing operation, checked with a noexcept expression. `executor.run<Op>(items, blocks)` must complete/join every submitted item before returning 0 or a negative fault. It runs local scans, computes block carries serially, and runs carry application. There is no allocation in this scan body and no concurrent reuse of one workspace is supported.", "Returns `-22` for zero capacity, count-to-byte overflow, null nonempty input/output, or partial overlap. Identical buffers and disjoint buffers are allowed; empty input succeeds after capacity validation. A negative executor result is propagated with already-written output retained. `scan_into` forwards to this member. `capacity()` reports maximum blocks, not maximum input elements.", "For `b = min(count, capacity)` nonempty blocks, work is `O(count + b)` operation calls and setup storage is `O(capacity)`. Parallel execution depends entirely on the executor; the provided serial executor performs both stages sequentially. Input, output, operation, and executor must remain live through the joined call.")),
            entry("micron::parallel::serial_scan_executor", "parallel/scan_workspace.hpp", "A scan executor that invokes each work item serially in index order.",
                section("Result and complexity", "`run<Op>(items, count)` returns the first negative operation result or zero after all items. It allocates no memory and performs linear item-dispatch work plus the operations themselves. It satisfies the scan workspace's joined-return contract without starting threads or a coroutine runtime. Exceptions cannot escape its noexcept call.")),
        ],
        "sources": ["parallel/algo.hpp", "parallel/compaction.hpp", "parallel/elementwise.hpp", "parallel/engine.hpp", "parallel/find.hpp", "parallel/for.hpp", "parallel/for_each.hpp", "parallel/memory.hpp", "parallel/numeric.hpp", "parallel/pipeline.hpp", "parallel/poll.hpp", "parallel/ranges.hpp", "parallel/reduce.hpp", "parallel/scan.hpp", "parallel/scan_workspace.hpp", "parallel/sort.hpp"],
    },
    "tasks": {
        "summary": "Lazy C++ coroutine tasks, continuation-stealing scheduling, manually resumed stackful routines, and asynchronous synchronization share frame/lifetime support but have distinct execution and ownership protocols.",
        "sections": [
            section("Execution models", columns=["Facility", "Execution and ownership", "Use"], rows=[
                ["`task<T>`", "Lazy coroutine; frame owned by a movable handle until transferred or destroyed.", "Awaitable computations with a value or void result."],
                ["`coro::fork` / `call` / `join`", "Run children with symmetric transfer; fork publishes a stealable parent continuation.", "Structured divide-and-conquer whose children finish before their bound storage dies."],
                ["`coro::schedule`, `sync_wait`, `detach`", "Submit an independent root to the global native worker engine.", "A future result, a blocking caller, or explicitly detached completion."],
                ["`coro::fork_group`", "Separate root tasks with one outstanding counter and borrowed group state.", "Dynamically added work joined from another coroutine frame."],
                ["`generator<T>`", "Single-pass coroutine resumed synchronously by its iterator.", "Pulling yielded values without a task scheduler."],
                ["`coro::routine<Y, R>`", "A manually jumped, stackful fiber retaining an ordinary function stack.", "Yielding from nested ordinary function calls."],
                ["`async_*` primitives", "Retain coroutine waiter nodes and resume continuations on notification.", "Waiting without deliberately parking the scheduler's native worker."],
            ]),
            section("Entry headers and runtime lifecycle",
                "Include `<micron/stdcoro.hpp>` before other task headers to select the io_uring reactor by default; define `MICRON_CORO_NO_URING` first to disable that default. Including a task/reactor header before the entry header can compile out the reactor and is diagnosed by the entry header. `<micron/coroio.hpp>` additionally includes the I/O umbrellas; it does not introduce another task type. Native stack switching and the task-based engine reject wasm.",
                "`start_coroutine_runtime(nworkers)` lazily initializes a global engine once, selecting `cpu_count()` for zero and clamping to 1 through 32 workers. Each worker is an owning `auto_thread`, with a private work deque, overflow list, and resident dispatch fiber. External roots enter a bounded 256-entry MPMC inbox; submission yields until it can insert. Default deques are growable from `MICRON_CORO_DEQUE_CAP` (1024); `MICRON_CORO_FIXED_DEQUE` uses the fixed variant.",
                "A worker pops local continuations LIFO, polls the inbox first every 64 searches, checks completions when enabled, and steals from other workers with a bounded randomized scan. Before parking it performs bounded CPU-pause searches, announces its park bit, and rechecks for work. Per-worker epoch futexes are the default; `MICRON_CORO_GLOBAL_SIGNAL` selects a shared signal word and is incompatible with the reactor. These heuristics do not guarantee FIFO scheduling or progress for a blocking callback.",
                "`stop_coroutine_runtime()` waits for repeated quiet observations, applies configurable no-progress grace periods to timers and I/O, wakes/join workers, shuts down rings and pooled segments, and clears global state. It is not a general cancellation/join of arbitrary tasks suspended on user synchronization. Timer waits can be cut and their list discarded after the grace period. Stop must run from an external coordinated owner without concurrent submission, restart, or outstanding borrowed engine/executor use; calling it from one of its workers can wait on or join itself. The runtime reaper calls stop during normal teardown."),
            section("Fork, call, join, and result binding",
                "`co_await fork(eventual, fn, args...)` constructs a child and binds its result to the supplied `eventual`. `fork(&slot, fn)(args...)` binds an existing assignable value; `fork(discard, fn)(args...)` discards the result. The bracket forms select the same binders. The current worker publishes the parent continuation before immediately transferring into the child. If publication is unavailable or a fixed deque is full, the child completes serially back to the parent.",
                "Forked callable parameters must be passed by value: reference parameters could refer to the binder's argument copy after a continuation is stolen. The source checks ordinary function and non-overloaded call-operator signatures; generic/overloaded callables may evade that check and still must obey the lifetime requirement. Capturing a pointer does not copy the pointed-to object. Result destinations and parent locals must remain live until `co_await join` completes.",
                "`co_await join` waits for detached/stolen child completions, destroys the parent's linked child frames, clears the join epoch, and surfaces the first recorded child error. At most 32767 outstanding steals fit one join epoch; exceeding that packed count traps. The first-child-error pointer is ordinary shared storage: simultaneous failures in separate children can race while recording it, so this is not a general synchronized exception-aggregation mechanism. No destructor implicitly joins forked children. Returning, unwinding, or destroying a parent before the join can leave children referencing dead parent/result storage.",
                "Unbound `call(fn, args...)` simply invokes the callable and returns its task for ordinary co_await. Result-bound `call(&slot, fn)(args...)` uses a serial symmetric-transfer child and destroys its frame with its awaitable. A bound child's runtime exception is not automatically surfaced by that awaitable's empty await_resume; an eventual binding records it, while raw/discard binding may leave no value/error indication. Fork construction/allocation failures are recorded for join, while call construction failure records an eventual error only when that binding is used."),
            section("Root submission, yielding, and timed waits",
                "`sync_wait(task&&)` starts the runtime, moves the root into a bridge, submits it, briefly CPU-spins, then futex-waits for a release-published done flag. `schedule(task&&)` returns `futex_future<T>` and completes its promise from a detached bridge. `detach(task&&)` supplies no result. The bridge unhandled-exception path traps; these APIs do not preserve and rethrow an arbitrary task exception as the original exception object. `sync_wait` does not check a null bridge allocation result before accessing it.",
                "`co_await futex_future` uses its state's single coroutine-waiter slot and returns `get()`. The future/state and engine must remain live. Only one pending coroutine waiter may register on a state. `coro::when_any(futures, n)` allocates a selection state and one node per future, returning the first observed ready index without consuming a result. Losing registrations remain until their producers complete; their futures/states must be retained. `n == 0` has no winner and suspends indefinitely, and overlapping registrations on the same state are unsupported.",
                "`reschedule()` republishes locally LIFO and may return inline off-engine or on deque failure. `reschedule_fair()` first tries the external inbox and drains some I/O, then falls back to the local route. Neither is a strict fairness or I/O-completion guarantee. `sleep_until` uses an absolute monotonic timespec; `sleep_for` counts nanoseconds and `sleep_for_ms` multiplies milliseconds without overflow checking. Sleep uses a ring timeout when available, otherwise a lazily created native timer thread scanning an intrusive list. Retain a sleeping frame until wake; the timer registration has no destructor unlink."),
            section("Bulk task creation",
                "`spawn_many(n, fn)` forks `fn(i)` into a vector of `n` already default-constructed slots, joins, and returns it. The result must be a nonvoid default-constructible, assignable element type; the slots stay stable during the loop. `spawn_tuple(tasks...)` and `when_all` similarly default-construct a heterogeneous tuple, fork each already-built task into its slot, and join. Void and nonassignable results are not supported by these aggregate result containers.",
                "`fork_task(&slot, task&&)` transfers an already constructed task into a fork awaitable and selects eventual or lvalue binding from the destination type. It does not by itself run a task; the returned awaitable must be awaited. Aggregate spawning allocates result storage and coroutine frames and uses linear setup/collection work plus the children. It inherits the per-join epoch and destination-lifetime bounds."),
            section("Coroutine synchronization and cancellation",
                "Async mutex/event/semaphore/barrier/latch/rwlock/condition-variable waits require promises derived from the scheduler's frame base. They store nodes in suspended frames and generally wake by engine submission or inline resume. They do not interoperate with an arbitrary foreign coroutine promise merely because it has a coroutine handle.",
                "Cancellation is cooperative. `cancellation_source::bind(task)` records a borrowed flag in that frame; structured fork and result-bound call inherit it. `co_await cancelpoint()` returns a boolean and neither throws nor automatically stops the task. Ordinary direct co_await of another task does not copy the parent's flag into that task. Mutex, condition, channel, and timer waits do not automatically unlink or complete on source cancellation.",
                "With the reactor, a source cancel also scans registered one-shot I/O operations and requests kernel cancellation by user_data. Group request-cancel only sets its own flag and does not call that source hook. Neither form permits destroying an in-flight awaitable or buffer before completion has been observed."),
            section("Fiber storage and ABI",
                "Fibers choose the first size class at least as large as the requested segment: 256 KiB, 512 KiB, 1 MiB, or 4 MiB, clamping larger requests to 4 MiB. Roughly three quarters are reserved for upward-growing coroutine frames and one quarter for the downward-growing C stack, with two guard pages; VA-granule rounding can add frame slack. The control block occupies the high end of the C stack, reducing usable call-stack bytes. `routine::stack_size()` reports that C-stack region, not the requested combined class size.",
                "Segments first carve from abcmalloc's VA reservation and commit frame/stack spans, then fall back to ordinary mapping. Fallback guard mprotect errors are ignored. Same-thread released segments enter a TLS freelist; cross-thread releases use a bounded per-class 64-entry pool or return the region. Coroutine frames use an aligned bump arena when a fiber is current and fall back to aligned heap allocation otherwise or on arena exhaustion. Each arena frame retains a segment reference; only the topmost current frame can rewind the bump cursor individually.",
                "Context switching has explicit amd64, i386, arm32, and arm64 register layouts. Native thread TLS is not switched per fiber. The default does not save x86 floating-point control modes; `MICRON_FIBER_FPENV` adds x86 control-word handling and masks sticky SSE status bits on save. ARM code saves ABI callee-saved floating registers, not an independent complete per-fiber floating environment. Code must not assume thread-local state or a changed FP environment belongs to a migrating coroutine."),
            section("Reactor and one-shot I/O",
                "With `MICRON_CORO_URING`, each worker owns a ring initialized on that worker and a separate 64-entry fallback ring accepts off-worker submission under a lock. Worker ring entries default to 256 (`MICRON_CORO_URING_ENTRIES`). Submission remains single-producer per worker ring; completion reaping is serialized per ring and may be performed by another worker. The setup uses no-SQ-array intent and the ring's compatible initialization path, rather than assuming every kernel supports the newest flags.",
                "The `coro::io` read/write/readv/writev, open/close/metadata, allocation/advice, splice/tee, socket, poll, and nop builders copy an SQE into a one-shot awaitable. Awaiting returns the kernel completion's signed 32-bit result: byte count/descriptor/mask or negative errno, depending on the operation. Read/write offset `u64(-1)` uses and advances the descriptor position. Paths, iovecs, address buffers, and data buffers are borrowed until completion, and the wrapper does not retry partial transfers.",
                "A submitted/suspended/done-early handshake prevents completion from resuming a frame before suspension commits. Missing rings produce `-38`, refused fixed-buffer registration `-95`, a pre-cancelled frame `-125`, and exhausted submission room after retry `-105`. `operation | after(ns)` submits the operation linked to a relative timeout SQE and reports the operation completion result; it does not return a separate timeout enum. The awaitable destructor removes its cancellation-registry link but does not make destruction before kernel completion safe.",
                "Fixed data uses a shared slab of eight 256-KiB slots. `acquire_fixed` returns a slot or -1, `fixed_ptr/size` expose its buffer and byte capacity, and `release_fixed` only returns its bitmap slot. Retain the slot until all using operations complete. Slab registration is lazy per ring and can be refused, for example by memlock limits. Sparse direct-file tables default to 256 slots per ring (`MICRON_CORO_FILE_SLOTS`, a nonzero multiple of 64); wave helpers keep ring id and slot ownership paired.",
                "`MICRON_CORO_STAGED_SUBMIT` batches worker submissions up to 16 SQEs before entering and flushes on progress/parking paths. `MICRON_CORO_STATS` enables counters; `io_stats()` otherwise returns zeros. Registered-buffer and ring sizes are tuning/storage choices, not throughput guarantees. They also do not validate an arbitrary pointer as belonging to a chosen fixed buffer."),
            section("Multishot and wave protocols",
                "`coro::io::mrecv_t` retains one multishot receive operation on its worker ring. Each event has a result, originating ring, optional provided-buffer id, and more-events flag. The provided pool defaults to 256 buffers of 8192 bytes per participating ring; `MICRON_CORO_PBUF_ENTRIES` is a power-of-two setting and `MICRON_CORO_PBUF_SZ` is the per-buffer byte size. A single consumer calls `mrecv_next`, inspects/uses data, then recycles each provided buffer exactly once after use.",
                "The event queue has twice the provided-buffer entry count and traps on overflow. Not returning buffers prevents their reuse; retaining a data pointer after recycle allows subsequent kernel writes to overwrite it. `mrecv_cancel` requests synchronous cancellation, drains completion events until no more are promised, recycles queued buffers, and resets the operation; the destructor calls it while live. Keep the operation alive until that drain finishes. Cancellation can wait and is not a bounded-step destructor.",
                "`wave.hpp` supplies lower-level ring/slot and batch-await support rather than an owning public wave container. The owner supplies the SQE array, completion-node array, and wave state and must keep them alive while any completion is outstanding. One batch completion resumes its owner after the last SQE; individual results remain in nodes. Waves do not register with the task cancellation source, so cancelling a source does not cut a batch short. Batch construction/destruction and result extraction belong to the higher I/O wrapper contract."),
        ],
        "types": [
            entry("micron::task", "tasks/task.hpp", "A lazy move-only coroutine owner storing its result in a promise or a caller-bound destination.",
                section("Ownership and result", "`promise_type` aliases `__task_promise<T>`; its void specialization stores completion without a value. Construction from a coroutine handle owns that frame. `release()` transfers the handle and empties the owner; `handle()` merely borrows it. Move transfers ownership, destroying the destination's old frame on assignment. Destruction immediately destroys an owned frame rather than running or joining it.", "`valid()` tests a nonnull frame and `done()` tests completed final suspension. `result()` requires both and reports a library error otherwise. It moves the inline result without clearing the value-state flag; repeated calls move again from the retained object. An empty/allocation-failed task is invalid. Reference-result instantiations are not provided by the union-based value storage.", "Rvalue `operator co_await` creates a non-owning awaiter that sets a continuation and symmetrically transfers into the child. The task object still owns the frame and must survive the await; temporary task lifetime normally supplies that. Unhandled exceptions are reduced to a fixed diagnostic string and surfaced through the library error path; the original exception object is not retained. Bound promise completion constructs an eventual, assigns a raw lvalue, or discards according to the binding mode.", "Frame allocation uses the current fiber's aligned arena or heap fallback. Handle operations are constant work; creating/destroying a frame includes parameter/local/result lifetimes. A frame suspended in a registered wait or with unfinished fork children cannot safely be destroyed merely because an owner handle is available."), covers=("micron::task::promise_type",)),
            entry("micron::coro::eventual", "tasks/frame.hpp", "An immovable construct-once result slot for a structured child task.",
                section("Value lifetime", "The primary template contains uninitialized union storage, a has-value flag, and an error-string pointer. Successful child return constructs `T` directly in that storage; destruction destroys it only if constructed. `get() &` returns its protected-by-join reference; rvalue dereference moves a result by value but leaves the stored object alive. Reading an error or reading a nonvoid slot before production reports a library error.", "The slot has no atomic readiness wait and does not retain a producing frame. Read only after the corresponding join/call completion, and do not overwrite a live constructed result with another child. The void specialization stores only error state; its successful dereference performs no readiness check. Copy and move are not available.")),
            entry("micron::coro::discard_t", "tasks/quasi_pointer.hpp", "An empty tag selecting evaluation without result storage for a bound fork or call.",
                section("Use", "The inline constant `coro::discard` is passed to the fork/call binder. It suppresses destination storage, not execution, lifetime obligations, child joining, or error recording for structured forks. It allocates no memory and carries no cancellation state.")),
            entry("micron::coro::manual_lifetime", "tasks/manual_lifetime.hpp", "Aligned inline union storage with explicit construction and destruction of `T`.",
                section("Protocol", "`construct(args...)` placement-constructs the object and returns its address. `destroy()` explicitly invokes the destructor. `get`, `ptr`, and arrow access storage without checking whether an object is live; cv/ref-qualified get preserves value category. The wrapper destructor intentionally does not destroy `T`. The caller must balance construction/destruction and never read inactive storage. Copying is deleted and no move is provided.", "The void specialization makes construct/destroy/get no-ops. The wrapper performs no allocation or synchronization. Costs are those of the chosen `T` operation; double construction, double destruction, and using inactive storage are unsupported.")),
            entry("micron::coro::worker", "tasks/coro_core.hpp", "A cache-line-aligned scheduler record holding one worker's continuation deque and dispatch state.",
                section("Storage and constraints", "The record contains a fixed or growable Chase-Lev deque, an owner-private overflow list, an active flag, resident fiber pointer, id, and inbox-poll cadence counter. Deque bottom operations belong to its worker; thieves use the steal interface. Direct field manipulation is scheduler-internal and does not transfer frame ownership. `current_worker()` returns the native thread's TLS record or null off-engine.", "The engine owns the worker array and destroys it after joining workers. A borrowed record becomes invalid when runtime stop releases that array. Initial deque allocation and growth follow the selected queue's contracts; the worker object is not a user-level task handle.")),
            entry("micron::coro::engine", "tasks/coroutine/cl_sched.hpp", "The native-worker continuation-stealing scheduler and externally submitted root inbox.",
                section("Submission and ownership", "`submit(frame)` requires a live resumable scheduler frame and can yield indefinitely while its 256-entry inbox is full. It does not clone, reference-count, or destroy an arbitrary submitted frame. Bridge/task protocols determine frame ownership. The global start/stop functions initialize workers, join them, drain supported runtime resources, and destroy the engine in the required order; directly destroying an active engine is unsupported.", "The engine's public fields are implementation state, not a thread-safe reconfiguration interface. A `noexcept` worker activation traps if an exception escapes its coroutine chain. Waiting on a blocking native syscall or native mutex inside a task blocks that worker; having a separate fiber stack does not automatically turn ordinary blocking code into an asynchronous operation. Runtime lifecycle and tuning are described above.")),
            entry("micron::coro::fork_group", "tasks/fork_group.hpp", "An immovable dynamic group of independently scheduled roots, with an outstanding count and coroutine joiners.",
                section("Spawn and join", "`spawn(fn, args...)` increments its count, builds a heap bridge, invokes the task-producing callable from that bridge, and submits an independent root. It discards the child's result and decrements the count after successful co_await completion. Bridge allocation failure undoes the count, with no returned failure indication. The bridge unhandled-exception path traps rather than propagating a stored group result.", "`join()` returns an awaiter that registers until the outstanding count is nonpositive; multiple joiners may register. No destructor joins or cancels members. The group must outlive all children, its cancellation tokens, and joiners. A join that observes zero does not prevent a concurrent later spawn; externally define the end of group submission.", "`request_cancel()` sets the group's flag. Children bind that flag and inherit it through structured forks, but request-cancel does not call the general source's I/O cancellation hook. It never decrements outstanding merely because cancellation was requested. Count arithmetic overflow and arbitrary destruction during active work are unsupported. Per-child setup uses constant bookkeeping plus frame/argument costs; waking all joiners is linear in their number."), TASK_WAIT_LIFETIME),
            entry("micron::coro::cancellation_token", "tasks/cancellation.hpp", "A copyable non-owning view of a cooperative cancellation flag.",
                section("Observation", "Default construction is unbound and never cancelled. Boolean conversion tests whether a source is bound, not whether cancellation was requested. `cancelled()` relaxed-loads the flag. It does not wait, register a callback, retain the source, or supply an acquire publication edge for unrelated source data. The source flag must outlive every token/frame using it.")),
            entry("micron::coro::cancellation_source", "tasks/cancellation.hpp", "An address-stable cancellation flag that can be borrowed by tasks and tokens.",
                section("Operations", "`cancel()` release-sets the flag and calls the current I/O cancellation hook if installed. `token()` returns a borrowed observer. `bind(task&)` assigns the flag address to an existing valid task frame; bind before concurrent execution. The source is noncopyable and no move operation is provided.", "Cancellation is permanent for the source; there is no reset. Polling itself is constant work, while cancel with the reactor scans registered I/O operations and performs cancellation syscalls for matching entries. The source must remain live until bound frames and registered operations finish. `cancelpoint()` returns a bool in the current frame and does not stop execution automatically.")),
            entry("micron::generator", "tasks/generator.hpp", "A lazy move-only synchronous single-pass coroutine range.",
                section("Iteration and values", "The nested `promise_type` stores a pointer to the currently yielded value and a diagnostic string. `begin()` resumes to the next yield; every additional begin advances again rather than creating an independent iterator. Prefix/postfix increment resume the same frame, and comparison with `sentinel` tests null or done. Postfix increment returns void. There is no random access, size cache, or multipass guarantee.", "`iterator::operator*` and arrow borrow the object passed to `co_yield`. Advancing or destroying the generator can end that object's lifetime. Reference-like yielded expressions still require an appropriately surviving referent; no copied yield buffer is provided. The arrow declaration is `T*`, so a reference `T` cannot form that return type and is not a supported general reference-generator specialization.", "Move transfers the coroutine handle; destruction destroys it and all live coroutine locals without completing iteration. Escaped exceptions become a fixed library-error diagnostic when advancement reaches done. No scheduler or worker thread is started by iteration. Iterator copies refer to the same frame and concurrent iteration is unsupported."), covers=("micron::generator::promise_type", "micron::generator::iterator", "micron::generator::sentinel")),
            entry("micron::coro::routine", "tasks/coroutine/routine.hpp", "A movable manually resumed stackful coroutine with yield type `Y` and final result type `R`.",
                section("Creation and transfer", "`spin<Y, Stack>(fn, args...)` decay-stores the callable/arguments in its fiber frame arena and returns a fresh lazy routine. Its callable consumes stored arguments as rvalues. `launch` additionally jumps to the first yield or completion. `yield_type` is `Y` and `result_type` is the callable result `R`. No global scheduler is required for manual jump.", "`jump()` resumes until yield/completion and returns `Y*` for a value-yielding routine, or a boolean for `Y = void`; completion returns null/false. A value routine that calls argument-free yield can also return null while still alive, so use done/alive for completion state. `yield(v)` retains the address of its argument on the suspended stack rather than copying it. The yielded expression's type is not checked against `Y`; mismatch leads to type-confused access.", "A yielded pointer remains valid only until the routine advances, is dismissed, or destroys that object. `finish()` repeatedly jumps and discards yields until done. `result()` finishes, moves the final nonvoid result, destroys its stored object, and permits only one successful extraction. It marks the result consumed before moving; a throwing move can leave no retryable result cleanup.", "Copying is deleted. Move transfers the fiber/control pointers. Destruction or `dismiss()` releases a fresh or completed routine with appropriate launch/result cleanup, but a suspended routine is abandoned without unwinding its ordinary function stack or destroying suspended callable locals. Destruction of a running activation traps. Cross-thread jump or destruction must be externally serialized; the plain pointer state is not a concurrent owner protocol.", "`native_handle()` borrows its fiber and `stack_size()` reports the C-stack portion. `done`, `started`, and `alive` are observations. Setup costs include a segment and callable construction; each jump adds constant context-switch work plus user work until the next yield. A routine can run or yield forever."), covers=("micron::coro::routine::yield_type", "micron::coro::routine::result_type")),
            entry("micron::fiber::fiber", "tasks/coroutine/fiber.hpp", "A stack-resident execution-context control block retaining its stack segment and coroutine-frame arena.",
                section("Execution protocol", "`create_fiber(entry, arg, requested_size, parent)` returns a fresh/recycled fiber or null on segment failure. The control block is embedded at the highest stack address and is not independently allocated. `resume(f, host)` switches into its saved context; `suspend_to_scheduler()` switches back through its current link. The entry trampoline marks running, calls entry, records an escaped exception when enabled, marks done, and returns to the scheduler context.", "`fiber_state` contains fresh, running, suspended, and done. Direct resume of a completed fiber or concurrent resumes are unsupported. `current()` is a native-thread TLS pointer. The refcount covers execution plus arena-backed coroutine frames; `destroy_fiber` drops the execution reference and recycles the segment only after all retained frames are freed. It does not unwind a suspended entry stack.", "Same-thread freelist reuse and cross-thread segment-pool routing reduce repeated mapping operations while retaining memory. `drain_freelist` applies to the calling thread; `drain_seg_pool` requires coordinated shutdown. The storage split, size-class clamp, alignment, and per-architecture context restrictions are described above."), covers=("micron::fiber::fiber_state",)),
            entry("micron::coro::waiter_node", "tasks/waiter_list.hpp", "A borrowed intrusive node containing a scheduler-frame pointer and next link.",
                section("Use", "Nodes are ordinarily embedded in suspended awaiters. A node may be linked in only one waiter list at a time and must remain live until removed. Linking does not retain a coroutine handle or arrange automatic destruction cancellation. Resumption can invalidate the node immediately, so wake walkers read its next link before submitting it.")),
            entry("micron::coro::waiter_list", "tasks/waiter_list.hpp", "A spinlock-protected intrusive LIFO list of borrowed coroutine waiter nodes.",
                section("Operations", "`push` prepends; `pop` removes the head; `pop_blocking` spins until one exists; `swap_all` detaches the complete list. `push_unless(node, open)` tests its predicate under the same lock as registration, closing the check/register race. `swap_all_under(fn)` runs a callback under the lock and detaches all only if it returns true. Those callbacks must not block or resume a coroutine.", "List methods do not themselves resume or destroy detached nodes. Wake helpers submit/resume their frames. Empty checking and individual link changes take constant work plus spin contention; waking a complete list is linear in its length. Copying is deleted; list lifetime must cover all linked nodes.")),
            entry("micron::coro::async_mutex", "tasks/async_sync.hpp", "A nonrecursive coroutine mutex storing unlocked/held sentinels or a stack of waiting awaiters in one atomic word.",
                section("Acquisition and release", "`co_await lock()` acquire-claims the unlocked sentinel or links the awaiter and suspends. `try_lock()` makes one strong attempt. Unlock either publishes unlocked or removes the newest waiter and hands it ownership before resuming it. Waiting is LIFO, so older waiters can starve. Unlocking an unlocked mutex is unsupported and interprets the sentinel as an invalid waiter pointer.", "There is no native-thread owner check, recursive count, timed acquisition, or automatic cancellation. Uncontended operations have constant atomic work; CAS retries and scheduler submission can wait. Use `co_await coro::scoped_lock(m)` for an owning guard after acquisition."), TASK_WAIT_LIFETIME),
            entry("micron::coro::async_lock_guard", "tasks/async_locks.hpp", "A movable scope owner for an already acquired `async_mutex`.",
                section("Acquisition and ownership", "`co_await coro::scoped_lock(m)` awaits the mutex and returns an owning guard. Direct construction from `(mutex_pointer, owned)` trusts the supplied ownership flag and does not acquire. Default construction is empty. Copying is deleted; move transfers state, releasing the destination's old ownership on assignment.", "`unlock()` and destruction release only retained ownership. `owns_lock()` observes this wrapper and `mutex()` borrows its pointer. There is no release-without-unlock member. The mutex must outlive the guard. Holding the guard across suspension is permitted by its lifetime protocol, but user lock order and progress still determine deadlock.")),
            entry("micron::coro::manual_reset_event", "tasks/async_sync.hpp", "A coroutine event that retains set state until explicitly reset.",
                section("Operations", "Construct with an optional initial set flag. Await returns immediately when set, otherwise it pushes a waiter onto the atomic stack. `set()` exchanges the set sentinel and resumes every detached waiter; repeated set is a no-op. `reset()` changes only the set sentinel back to unset, leaving an existing pending waiter stack intact. `is_set()` acquire-loads a snapshot.", "State changes are constant atomic work; set takes linear work in the number of detached waiters. The event supplies no counted permits, value result, timed wait, or cancellation/unlink operation. Copying and moving are unavailable."), TASK_WAIT_LIFETIME),
            entry("micron::coro::async_semaphore", "tasks/async_sync.hpp", "A coroutine permit counter with a spinlocked LIFO stack of waiting acquisitions.",
                section("Permit and abort protocol", "Start with a nonnegative permit count. Awaited `acquire()` decrements the counter; a positive prior count returns true immediately, otherwise it registers a waiter. `release(n)` adds one permit at a time and marks/resumes each owed waiter. `try_acquire` consumes one positive permit, and `try_acquire_many(n)` consumes up to the requested positive count. They return false/zero after abort.", "There is a registration interval between the awaited counter decrement and waiter insertion. A releaser seeing that negative reservation busy-waits until a waiter appears, so release is not a bounded nonblocking operation and can stall a native worker if the waiter cannot complete registration. Arbitrary negative initial counts likewise cannot be used as unregistered debt.", "`abort()` permanently sets the aborted flag, wakes registered acquisitions with false rather than a permit, and posts until the count reaches at least 256. It is a close/wake mechanism, not reset; it can perform work proportional to waiters plus those extra posts. Release with nonpositive `n` performs no additions. Counter overflow is unchecked. `acquire` after abort returns false immediately."), TASK_WAIT_LIFETIME),
            entry("micron::coro::async_latch", "tasks/async_latch.hpp", "A one-shot coroutine completion counter satisfied at a nonpositive value.",
                section("Operations", "`try_wait()` acquire-tests the count. `count_down(n)` atomically subtracts `n` and wakes all when crossing from positive to nonpositive. Unlike the native latch, it neither ignores negative `n` nor clamps excessive decrement: negative values increase the count, and overflow is unchecked. Await uses prepare/recheck insertion under the waiter-list lock to avoid missed completion.", "There is no reset or automatic arrive-and-wait operation. Counter updates have constant atomic work; a crossing wake takes linear work in waiters. Copying and moving are unavailable."), TASK_WAIT_LIFETIME),
            entry("micron::coro::async_barrier", "tasks/async_barrier.hpp", "A reusable fixed-threshold coroutine barrier with generation-checked waiter registration.",
                section("Arrival", "Construction requires a positive threshold for meaningful use; zero is not rejected and underflows the arrival counter. `co_await arrive_and_wait()` decrements it. The last arrival restores the threshold, advances the generation while holding the waiter-list lock, and resumes all prior waiters. That last arrival continues immediately; other awaiters register unless the generation already changed.", "Every generation requires exactly the original number of arrivals. There is no drop, reset, completion callback, or cancellation member. Missing arrivals can suspend forever, and generation wrap over an observation interval is unsupported. Atomic arrival work is constant except for retries; completing a generation wakes a linear number of waiters."), TASK_WAIT_LIFETIME),
            entry("micron::coro::async_condvar", "tasks/async_condvar.hpp", "A coroutine condition wait that releases and later reacquires an `async_mutex`.",
                section("Condition protocol", "`wait(m)` returns a lazy `task<void>`; the caller must own `m` when that task runs. It registers an internal node, unlocks the mutex, waits for notification with a signal/park handshake, then awaits mutex reacquisition before completion. Test the actual shared predicate in a loop while owning the mutex; notification itself carries no predicate value.", "`notify_one()` signals the newest waiter; `notify_all()` detaches and signals all. Notify without waiters is not remembered. The handoff handles notification during suspension registration, but does not add an ownership check to the supplied mutex. Notification work is constant for one or linear for all, apart from list contention and engine submission."), TASK_WAIT_LIFETIME),
            entry("micron::coro::async_rwlock", "tasks/async_rwlock.hpp", "A coroutine reader-writer lock with spinlocked state, separate LIFO waiter lists, and queued-writer preference.",
                section("Locking protocol", "Await `lock_shared()` for a reader or `lock()` for a writer, and balance with `unlock_shared()` or `unlock()`. New readers are admitted only with no active writer and no queued writer. The last reader grants the newest waiting writer. Writer unlock grants another writer first; if none wait it admits the entire reader list together.", "Grant/park handshakes allow a waiter to be granted before it publishes its frame without losing the wake. No try-lock, timed operation, upgrade/downgrade, ownership validation, or scope guard is supplied. Mismatched unlock, recursive acquire, counter overflow, and early waiter destruction are unsupported. Reader batches can wait indefinitely under continuing writer arrivals. Single admission/release has constant state work; releasing a reader batch walks and wakes that batch."), TASK_WAIT_LIFETIME),
            entry("micron::chan_status", "tasks/async_channel.hpp", "A nonblocking channel-receive status: `ok`, `empty`, or `closed`.",
                section("Receive result", "`chan_pull<T>` contains `bool ok` and an owned `T value`. Awaited pulls return true with a moved received value, or false with `T{}` when closed and drained. `chan_status::empty` means no value was obtained from a still-open channel at that observation; concurrent producers/close can immediately change the state. These result types add no channel ownership or synchronization."), covers=("micron::chan_pull",)),
            entry("micron::async_channel", "tasks/async_channel.hpp", "A bounded FIFO MPMC channel combining a Crossbeam ring with coroutine item/space semaphores.",
                section("Capacity and transfer", "`Cap` defaults to 256 and should be positive. The ring rounds its allocation to a power-of-two capacity, while the space semaphore starts at exactly `Cap`, so channel admission uses `Cap` slots even when the ring has more physical slots. The ring allocation is owned by the channel; values are constructed/published and consumed according to that queue's type constraints. Pull paths also require `T{}`.", "Awaited `push(T)` waits for space, rejects a closed channel, publishes the moved value, and posts an item. `pull()` waits for an item and returns `chan_pull<T>`. Bulk push copies a source span; bulk pull move-assigns a destination span and returns the transferred count. Those spans are borrowed until completion. Bulk counts are converted to signed 64-bit permit requests and must be representable.", "`post(T)` and `try_pull(out)` do not deliberately suspend for missing space/items, but can spin on a reserved ring cell or while semaphore release waits for registration. They are not bounded-step lock-free calls. `close()` marks closed and aborts both semaphores, waking blocked operations; consumers can drain already buffered values. A producer that passed a close check can still race close and publish, so externally order final closure before treating closed-and-drained as permanent.", "There is no reopening. Destroy only after all producers/consumers and suspended operations finish. Steady transfer uses constant queue/permit bookkeeping excluding contention and element costs; bulk work is linear in transferred values, and close can wake a linear number of waiters."), TASK_WAIT_LIFETIME),
            entry("micron::sync_channel", "tasks/sync_channel.hpp", "A bounded FIFO MPMC channel using native futex-backed permit waits.",
                section("Operations and limits", "`Cap` defaults to 256, with exactly `Cap` admission permits over a power-of-two Crossbeam ring allocation. `push(T)` waits for space and rejects close; `pull(out)` waits for an item and returns true for a received value or false when closed and drained. `try_push`/`try_pull` test permits but can still spin on queue publication/consumption. `close()` aborts both native semaphores and permits buffered draining.", "The underlying `basic_semaphore::wait` can return on unexpected futex errors without obtaining a permit; the channel does not distinguish that result before spinning on its ring. Count overflow, misuse of reset/abort externally, and premature destruction remain unsupported. Blocking use inside a task parks the native worker. Producer close races can publish after an earlier open check; coordinate shutdown explicitly. Copying/moving are unavailable.")),
            entry("micron::unbounded_channel", "tasks/unbounded_channel.hpp", "An allocated FIFO linked-node channel with coroutine receive waits and no space backpressure.",
                section("Storage and operations", "`push(T)` checks close, allocates one value node, appends it under an internal spinlock, and posts the item semaphore. It returns a bool rather than a task. `pull()` awaits an item, removes the head under the lock, then moves/destroys its node and returns `chan_pull<T>`. `try_pull(out)` returns a status after a permit/closed check and direct list removal.", "`close()` marks closed and aborts the item semaphore; existing nodes can drain. Push only checks close before allocation/append, so an in-flight producer can append after close or a prior drained observation. There is no capacity bound beyond allocation resources. An exception while moving a removed value can bypass node deletion, while try-pull's noexcept interface cannot propagate a throwing assignment.", "Destruction deletes remaining nodes but neither wakes nor waits for consumers; all registrations must finish first. Each normal push/pop has constant list work plus allocation/deallocation, permit handoff, and element costs. Destruction is linear in buffered values. Copying/moving are unavailable."), TASK_WAIT_LIFETIME),
            entry("micron::coro::io::timeout", "tasks/coroutine/aio.hpp", "A relative nanosecond timeout tag for a one-shot reactor operation.",
                section("Use", "`after(ns)` returns this tag. Piping an unsubmitted one-shot awaitable into it returns a timed awaitable with the same operation/fixed-buffer requirement and a linked timeout SQE. Both SQEs are reserved together; failure returns an error instead of silently submitting untimed. It borrows all original operation data and does not own a descriptor or buffer.")),
            entry("micron::coro::io::mrecv_t", "tasks/coroutine/aio.hpp", "An immovable owner of multishot-receive state whose kernel user_data points into the object.",
                section("Arm, consume, cancel", "`mrecv_arm` requires the current worker's live ring and provided-buffer registration, returns 0 on successful submission, `-95` for unsupported setup, `-114` if already armed, or `-105` for no submission room. `mrecv_next` awaits one event; inactive/drained state synthesizes `-61`. Only one consumer may await/pop this event queue.", "`mrecv_data(event)` borrows the provided buffer when present; `mrecv_recycle(event)` returns it to its originating ring. Process each event and recycle its buffer exactly once, retaining data only until recycle. `mrecv_live` tests whether more kernel completions remain promised. `mrecv_cancel` and the live destructor synchronously cancel and drain before the state can die; they may wait indefinitely on kernel/reaper progress. Concurrent destruction, consume, and rearm are unsupported.")),
            entry("micron::coro::io_stats_t", "tasks/coroutine/reactor.hpp", "A value snapshot of aggregate coroutine-reactor activity counters.",
                section("Fields and observation", "Fields count submits, enters, inline completions, SQ-full flushes, parks, wakes, and cancels. `io_stats()` sums relaxed-loaded per-ring counters with `MICRON_CORO_STATS`, otherwise returns zeros. The snapshot is not atomic across counters or rings. `io_pending()` similarly sums in-flight logical-operation counters; it is not a retained-task count or a stable completion fence. These APIs are present only with the reactor enabled.")),
        ],
        "sources": ["tasks/async_barrier.hpp", "tasks/async_channel.hpp", "tasks/async_condvar.hpp", "tasks/async_latch.hpp", "tasks/async_locks.hpp", "tasks/async_rwlock.hpp", "tasks/async_sync.hpp", "tasks/cancellation.hpp", "tasks/coro_core.hpp", "tasks/coroutine/aio.hpp", "tasks/coroutine/cl_sched.hpp", "tasks/coroutine/fiber.hpp", "tasks/coroutine/fiber_stack.hpp", "tasks/coroutine/reactor.hpp", "tasks/coroutine/routine.hpp", "tasks/coroutine/wave.hpp", "tasks/fork_group.hpp", "tasks/fork_join.hpp", "tasks/frame.hpp", "tasks/generator.hpp", "tasks/manual_lifetime.hpp", "tasks/quasi_pointer.hpp", "tasks/spawn.hpp", "tasks/sync_channel.hpp", "tasks/task.hpp", "tasks/tasks.hpp", "tasks/unbounded_channel.hpp", "tasks/waiter_list.hpp", "coroio.hpp", "stdcoro.hpp", "bits/__ar.hpp", "memory/stack_constants.hpp"],
    },
}
